{
  "sop_id": "SOP-014",
  "title": "Purchase Requests – procurement desk notes",
  "steps": [
    {
      "step_id": "S1",
      "name": "Buyer raises ticket and self-assigns",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Validate item descriptions, quantities, specs, and required-by date",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Look up budget head and cost centre on the latest budget report",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Decide sourcing method (rate contract, competitive quotes, or single source) and estimate value",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S5",
      "name": "Write up PR note and submit",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "D1",
      "name": "Wait for budget availability confirmation from Finance's budget control team",
      "role": "System",
      "type": "intake"
    },
    {
      "step_id": "A1",
      "name": "Incharge reviews the PR",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "A2",
      "name": "Lead approves the PR",
      "role": "Lead",
      "type": "approval"
    },
    {
      "step_id": "A3",
      "name": "HOD signs off if PR value exceeds ten lakh rupees",
      "role": "HOD",
      "type": "approval"
    },
    {
      "step_id": "R1",
      "name": "Escalate to Lead if PR is rejected twice",
      "role": "Lead",
      "type": "decision"
    },
    {
      "step_id": "R2",
      "name": "Attach justification for single-source buy (if applicable)",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "R3",
      "name": "Correct and resubmit rejected PR",
      "role": "Executor",
      "type": "rework"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    },
    {
      "stage": "Lead",
      "condition": "always"
    },
    {
      "stage": "HOD",
      "condition": "PR value > 10 lakh rupees"
    }
  ],
  "dependencies": [
    {
      "dep_id": "D1",
      "provider": "Finance",
      "item": "budget availability confirmation",
      "parallel_group": "P1"
    }
  ],
  "rework_reasons": [
    "Wrong quantity",
    "Amount mismatch",
    "Incorrect category",
    "Required document missing"
  ],
  "first_pass_yield_target": 0.90
}
